create table public.ah_products (
 id text primary key check (id ~ '^[a-z0-9_-]{1,40}$'),
 data jsonb not null check (jsonb_typeof(data) = 'object'),
 version integer not null default 1 check (version > 0),
 sort_order integer not null default 1000,
 created_at timestamptz not null default now()
);
alter table public.ah_products enable row level security;
revoke all on public.ah_products from public, anon, authenticated;
grant select, insert, update on public.ah_products to service_role;
insert into public.ah_products (id,data,sort_order)
